import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAException.h>

// Fast tanh built on the __expf intrinsic (fast math).
// tanh(x) = 1 - 2 / (exp(2x) + 1); numerically safe for large |x|
// because exp(2x) saturates to +inf (result -> 1) or 0 (result -> -1).
__device__ __forceinline__ float fast_tanhf(float v) {
    return 1.0f - __fdividef(2.0f, __expf(2.0f * v) + 1.0f);
}
// Vectorized (float4) tanh kernel for bulk of the data.
__global__ void tanh_kernel_vec4(const float4* __restrict__ x,
                                 float4* __restrict__ y,
                                 long long n4) {
    const long long stride = (long long)gridDim.x * blockDim.x;
    for (long long i = (long long)blockIdx.x * blockDim.x + threadIdx.x; i < n4; i += stride) {
        float4 v = __ldcs(x + i);
        v.x = fast_tanhf(v.x);
        v.y = fast_tanhf(v.y);
        v.z = fast_tanhf(v.z);
        v.w = fast_tanhf(v.w);
        __stcs(y + i, v);
    }
}
// Scalar kernel to handle any leftover tail elements.
__global__ void tanh_kernel_scalar(const float* __restrict__ x,
                                   float* __restrict__ y,
                                   long long start,
                                   long long n) {
    const long long stride = (long long)gridDim.x * blockDim.x;
    for (long long i = start + (long long)blockIdx.x * blockDim.x + threadIdx.x; i < n; i += stride) {
        y[i] = fast_tanhf(x[i]);
    }
}

torch::Tensor tanh_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "Input must be float32");

    auto xc = x.contiguous();
    auto y = torch::empty_like(xc);

    long long n = xc.numel();
    if (n == 0) {
        return y;
    }

    const float* xp = xc.data_ptr<float>();
    float* yp = y.data_ptr<float>();

    long long n4 = n / 4;
    long long tail_start = n4 * 4;
    // If either pointer is not 16-byte aligned (e.g., a sliced view),
    // skip the float4 fast path and let the scalar kernel handle everything.
    bool aligned16 = (reinterpret_cast<uintptr_t>(xp) % 16 == 0) &&
                     (reinterpret_cast<uintptr_t>(yp) % 16 == 0);
    if (!aligned16) {
        n4 = 0;
        tail_start = 0;
    }

    const int threads = 512;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    const long long max_blocks = 65535;
    if (n4 > 0) {
        long long blocks = (n4 + threads - 1) / threads;
        blocks = blocks < max_blocks ? blocks : max_blocks;
        tanh_kernel_vec4<<<(unsigned int)blocks, threads, 0, stream>>>(
            reinterpret_cast<const float4*>(xp),
            reinterpret_cast<float4*>(yp),
            n4);
        C10_CUDA_KERNEL_LAUNCH_CHECK();
    }
    if (tail_start < n) {
        long long remaining = n - tail_start;
        long long blocks = (remaining + threads - 1) / threads;
        blocks = blocks < max_blocks ? blocks : max_blocks;
        tanh_kernel_scalar<<<(unsigned int)blocks, threads, 0, stream>>>(
            xp, yp, tail_start, n);
        C10_CUDA_KERNEL_LAUNCH_CHECK();
    }
    return y;
}
"""

cpp_src = "torch::Tensor tanh_forward(torch::Tensor x);"

tanh_module = load_inline(
    name="tanh_cuda_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["tanh_forward"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs Tanh activation using a custom CUDA kernel.
    """

    def __init__(self):
        super(ModelNew, self).__init__()
        self._tanh = tanh_module.tanh_forward

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._tanh(x)

